"use client";
import { useId, useRef, type ReactNode } from "react";
import { useScrollMotion, scrollStage, type ScrollMotionProps } from "./scroll-shared";
import { scrollLerp } from "./scroll-math";
export interface MaskRevealProps extends ScrollMotionProps {
  children: ReactNode;
  shape?: "circle" | "rectangle" | "ellipse" | "organic" | "custom";
  direction?: "open" | "close";
  startSize?: number;
  borderRadius?: number /** SVG path in normalized 0–1 coordinates. */;
  path?: string;
}
const scrollBlob =
  "M .5 0 C .8 -.04 1 .15 1 .47 C 1.02 .74 .78 1 .51 1 C .22 1.04 0 .82 0 .51 C -.03 .2 .2 .03 .5 0 Z";
export function MaskReveal({
  children,
  shape = "circle",
  direction = "open",
  startSize = 0.04,
  borderRadius = 18,
  path = scrollBlob,
  ...props
}: MaskRevealProps) {
  const root = useRef<HTMLDivElement>(null),
    id = `scroll-mask-${useId().replace(/:/g, "")}`;
  useScrollMotion(
    root,
    props,
    ({ progress: p, reduced }) => {
      const q = reduced ? 1 : scrollLerp(startSize, 1, direction === "close" ? 1 - p : p),
        el = root.current!.querySelector<HTMLElement>("[data-scroll-mask]")!;
      if (shape === "circle") el.style.clipPath = `circle(${q * 72}% at 50% 50%)`;
      else if (shape === "ellipse") el.style.clipPath = `ellipse(${q * 72}% ${q * 85}% at 50% 50%)`;
      else if (shape === "rectangle")
        el.style.clipPath = `inset(${(1 - q) * 50}% round ${borderRadius * (1 - q)}px)`;
      else {
        const scale = q * 1.6;
        el.style.clipPath = reduced || q >= 0.999 ? "none" : `url(#${id})`;
        root
          .current!.querySelector("[data-scroll-outline]")!
          .setAttribute(
            "transform",
            `translate(${0.5 - scale / 2} ${0.5 - scale / 2}) scale(${scale})`,
          );
      }
    },
    `${shape}:${direction}:${startSize}:${borderRadius}:${path}`,
  );
  return (
    <div
      ref={root}
      data-scroll-animation="mask-reveal"
      className={props.className}
      style={{ ...scrollStage, ...props.style }}
    >
      <svg aria-hidden="true" width="0" height="0" style={{ position: "absolute" }}>
        <defs>
          <clipPath id={id} clipPathUnits="objectBoundingBox">
            <path data-scroll-outline="" d={path} />
          </clipPath>
        </defs>
      </svg>
      <div data-scroll-mask="" style={{ width: "100%", height: "100%" }}>
        {children}
      </div>
    </div>
  );
}
